def compute(vars):
    total_maturities = vars["v2"]
    thereafter_maturities = vars["v1"]

    if total_maturities == 0:
        return None

    ratio = thereafter_maturities / total_maturities
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "thereafter_maturities": thereafter_maturities,
            "total_maturities": total_maturities,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
